settings.markdownTextFunction:
// 整体无数据兜底
if (!data || !data.length || !data[0]) {
  return '<div class="main-content" style="display:flex;align-items:center;justify-content:center;height:100%;color:#999;">暂无数据</div>';
}

var firstData = data[0];

// 补零工具
function padZero(num) {
  var str = String(num);
  return str.length < 2 ? '0' + str : str;
}

// 时间处理
function updateCurrentTime(time) {
  if (!time) return '--';
  var now = new Date(time);
  if (isNaN(now.getTime())) return '--';

  return now.getFullYear() + '年' +
    padZero(now.getMonth() + 1) + '月' +
    padZero(now.getDate()) + '日 ' +
    padZero(now.getHours()) + ':' +
    padZero(now.getMinutes()) + ':' +
    padZero(now.getSeconds());
}

// 1. 桩号处理：空值、非数字直接返回 '--'
function formatNumberToKNotation(number) {
  if (number === null || number === undefined || number === '' || isNaN(Number(number))) {
    return '--';
  }

  var numStr = String(number);
  var parts = numStr.split('.');
  var integerPart = parts[0];
  var decimalPart = parts[1] ? parts[1].substring(0, 2) : '';

  if (integerPart.length <= 3) {
    return 'K000+' + integerPart + (decimalPart ? '.' + decimalPart : '');
  }

  var kPart = integerPart.slice(0, -3);
  while (kPart.length < 3) {
    kPart = '0' + kPart;
  }

  var plusPart = integerPart.slice(-3) + (decimalPart ? '.' + decimalPart : '');
  return 'K' + kPart + '+' + plusPart;
}

// 2. 状态处理：不在有效枚举内或为空时返回 '--'，不再 default 到“正常”
function formatResult(result) {
  if (!result) return '--';

  switch (result) {
    case 'MAJOR':
      return '<span style="background: #FFC37C; border-radius: 4px; color: #262626; font-weight: bold; padding: 2px 6px; font-size: 12px;">中度离析</span>';
    case 'NORMAL':
      return '<span style="background: #03BC81; border-radius: 4px; color: #FFFFFF; font-weight: bold; padding: 2px 6px; font-size: 12px;">正常</span>';
    case 'MINOR':
      return '<span style="background: #FFF78C; border-radius: 4px; color: #262626; font-weight: bold; padding: 2px 6px; font-size: 12px;">轻度离析</span>';
    case 'CRITICAL':
      return '<span style="background: #FF7C7C; border-radius: 4px; color: #FFFFFF; font-weight: bold; padding: 2px 6px; font-size: 12px;">重度离析</span>';
    default:
      return '--';
  }
}

// 3. 图片渲染：有地址渲染 img，无地址显示优雅的空状态 UI 盒子
function renderImage(url) {
  if (url && typeof url === 'string' && url.trim() !== '') {
    return '<img class="img-content" src="' + url + '" style="width:100%;height:100%;object-fit:cover;display:block;" onerror="this.parentElement.innerHTML=\'<div class=\\\'empty-img-box\\\'>暂无图片数据</div>\'" />';
  }
  return '<div class="empty-img-box" style="width:100%;height:100%;min-height:220px;background:#f5f7fa;border:1px dashed #dcdfe6;border-radius:4px;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#909399;font-size:13px;">' +
      '<svg style="width:36px;height:36px;fill:#c0c4cc;margin-bottom:8px;" viewBox="0 0 1024 1024"><path d="M928 160H96c-17.7 0-32 14.3-32 32v640c0 17.7 14.3 32 32 32h832c17.7 0 32-14.3 32-32V192c0-17.7-14.3-32-32-32zm-40 632H136v-39.9l138.5-164.3 150.1 125.8 262.3-261.6 193.1 240.2V792h8zM304 456c-48.6 0-88-39.4-88-88s39.4-88 88-88 88 39.4 88 88-39.4 88-88 88z"></path></svg>' +
      '<span>暂无监控画面</span>' +
    '</div>';
}

return '<div class="main-content">' +
  '<div class="carousel-content" style="overflow:hidden;border-radius:4px;">' +
      renderImage(firstData.urlPre) +
  '</div>' +
  '<div class="info-content" style="padding-top:12px;">' +
    '<div class="now-time" style="font-size:16px;font-weight:bold;margin-bottom:12px;color:#333;">' + updateCurrentTime(firstData['urlPre|ts']) + '</div>' +
    '<div class="info-item" style="margin-bottom:8px;color:#666;"><span class="item-title" style="color:#999;margin-right:8px;">实时施工桩号:</span>' + formatNumberToKNotation(firstData.chainage) + '</div>' +
    '<div class="info-item" style="margin-bottom:8px;color:#666;"><span class="item-title" style="color:#999;margin-right:8px;">摊铺车牌号:</span>' + (firstData.car || '--') + '</div>' +
    '<div class="info-item" style="display:flex;align-items:center;color:#666;"><span class="item-title" style="color:#999;margin-right:8px;">离析监测状态:</span>' + formatResult(firstData.result) + '</div>' +
  '</div>' +
'</div>';

